+
+jobs:
+  pr-gate:
+    # 1. for commits on main: no gating needed
+    # 2. for workflow_dispatch: this can only be triggered by users with write access
+    # 3. for pull_request and pull_request_target: apply the checks below.
+    #    This job only reads PR metadata through the API and never checks out
+    #    or executes PR code, so it is safe for pull_request_target callers.
+    runs-on: ubuntu-latest
+    env:
+      IS_PR_EVENT: ${{ github.event_name == 'pull_request' || github.event_name == 'pull_request_target' }}
+    steps:
+      - name: Fetch latest PR info
