+    if ((hardware === 'mi300x') && quantization !== 'fp16') {
+      return '# Error: MI300X + DeepSeek-OCR only supports FP16 quantization\n# Please select FP16 quantization';
+    }
+
+    // Model path
+    let modelPath = 'deepseek-ai/DeepSeek-OCR';
