+    const hwConfig = modelConfigs[hardware].fp8;
+    const tpValue = hwConfig.tp;
+
+    let cmd = 'sglang serve \\\n';
+    cmd += `  --model-path ${modelName}`;
+    cmd += ` \\\n  --tp ${tpValue}`;
