+        Err(env::VarError::NotPresent) => Ok(MAX_CONCURRENT_STREAMS),
+        Err(env::VarError::NotUnicode(_)) => Err(io::Error::new(
+            io::ErrorKind::InvalidInput,
+            format!("{MAX_CONCURRENT_STREAMS_ENV} must be valid UTF-8"),
+        )),
+    }
