+                namespace: Some("sgl-router-test".into()),
+                ..Default::default()
+            },
+            address_type: "IPv4".into(),
+            endpoints: entries
+                .iter()
+                .map(|(addr, ready)| Endpoint {
+                    addresses: vec![(*addr).to_string()],
+                    conditions: ready.map(|r| EndpointConditions {
+                        ready: Some(r),
+                        ..Default::default()
+                    }),
+                    ..Default::default()
+                })
+                .collect(),
+            ports: port.map(|p| {
+                vec![EndpointPort {
+                    port: Some(p),
+                    ..Default::default()
+                }]
