+/// Builds the top-level `score_policy`.
+fn build_score_policy(
+    model: &ModelConfig,
+    tree: &Arc<HashTree>,
+    oracle: &Arc<BlockSizeOracle>,
+) -> Result<Arc<dyn Policy>> {
+    Ok(Arc::new(ScorePolicy::new(build_fused(
+        model, tree, oracle,
+    )?)))
+}
