+pub fn build_registry(
+    cfg: &Config,
+    tree: Arc<HashTree>,
+    block_size_oracle: Arc<BlockSizeOracle>,
+) -> Result<PolicyRegistry> {
+    let reg = PolicyRegistry::default();
+    let m = &cfg.model;
+    reg.insert(
+        ModelId(m.id.clone()),
+        build_policy(m, Arc::clone(&tree), Arc::clone(&block_size_oracle))?,
+    );
+    Ok(reg)
+}
