+        Self::default()
+    }
+}
+
+impl Policy for RoundRobinPolicy {
+    fn select(&self, workers: &[Arc<Worker>], _ctx: &SelectionContext<'_>) -> Option<Arc<Worker>> {
+        if workers.is_empty() {
+            return None;
+        }
+        let i = self.counter.fetch_add(1, Ordering::Relaxed) % workers.len();
+        Some(workers[i].clone())
+    }
+}

