+    /// [`snapshot`] fixture pins at zero.
+    fn queued_snapshot(entries: &[(&Arc<Worker>, u64, u64, u64)]) -> EngineReportedLoadSnapshot {
+        EngineReportedLoadSnapshot::from_native_cache_workers(
+            7,
+            entries
+                .iter()
+                .map(|(worker, waiting, used, capacity)| {
+                    (
+                        worker.url.clone(),
