+        let dst = HashTree::new();
+        dst.restore_snapshot(&worker_table, &nodes).unwrap();
+
+        for i in 0..N_SHARDS {
+            assert_eq!(
+                dst.shards[i].read().node_count(),
+                src.shards[i].read().node_count(),
