+    /// Like `build_block_stored_bytes`, but `token_ids` is the bigram
+    /// list-of-pairs shape that DeepSeek-V4-class models emit.
+    fn build_block_stored_bigram_bytes(
+        block_hashes: &[i64],
+        parent: Option<i64>,
+        token_pairs: &[(u32, u32)],
+        block_size: u32,
+        lora_id: Option<i64>,
+        medium: Option<&str>,
+    ) -> Vec<u8> {
+        let mut buf = Vec::new();
+        write_event_map(
+            &mut buf,
+            "BlockStored",
