+        rmp::encode::write_str(&mut full, "LoadStat").unwrap();
+        for value in [2, 3, 4, 100] {
+            rmp::encode::write_u64(&mut full, value).unwrap();
+        }
+        rmp::encode::write_nil(&mut full).unwrap();
+        for value in [500, 600, 32, 1_000, 2_000] {
+            rmp::encode::write_u64(&mut full, value).unwrap();
