+        let inputs: Vec<String> = (0..10).map(|i| format!("hello {i}")).collect();
+        let expected: Vec<Vec<u32>> = inputs
+            .iter()
+            .map(|s| adapter::encode(&t, s).unwrap())
+            .collect();
