+fn probe_queries() -> Vec<Vec<i64>> {
+    let mut q = vec![
+        vec![1],
+        vec![1, 2],
+        vec![1, 2, 3],
+        vec![1, 2, 3, 4],
+        vec![1, 2, 5],
+        vec![1, 2, 5, 6],
+        vec![1, 2, 3, 4, 12345],
+        vec![7],
+        vec![2],
+        vec![2, 3],
+        vec![2, 3, 9],
+        vec![404],
+        vec![],
+    ];
+    for r in 0..64i64 {
+        q.push(vec![r * 4096 + 11]);
+        q.push(vec![r * 4096 + 11, r * 4096 + 12]);
+        q.push(vec![r * 4096 + 11, r * 4096 + 99]);
+    }
+    q
+}
