+    let (base_url, _server) = spawn_app(Router::new().route(
+        "/echo-accept-encoding",
+        get(|headers: HeaderMap| async move {
+            headers
+                .get(header::ACCEPT_ENCODING)
+                .and_then(|v| v.to_str().ok())
+                .unwrap_or("<absent>")
+                .to_string()
