+fn bucket(id: &str, max: Option<u64>, policy: Arc<dyn Policy>) -> Bucket {
+    let mut bucket = Bucket::new(id, BucketGroups::Plain(EngineGroup::new(policy)));
+    bucket.limits.max = max;
