+/// SGLang's native `/generate` response shape, echoing the request's `rid`.
+#[allow(dead_code)] // Used by `MockWorker::start`, only some test files need it.
+async fn generate(
+    State(s): State<MockWorkerState>,
+    headers: HeaderMap,
+    body: Bytes,
