+    let rank = send(&app, &worker, &[(KEY, "conv-a")]).await.unwrap();
+    for _ in 0..3 {
+        let spoofed = [(KEY, "conv-a"), (RANK, "9")];
+        assert_eq!(send(&app, &worker, &spoofed).await.as_ref(), Some(&rank));
