+    // A batch needs a list of rids, so none is minted.
+    send(&app, json!({"model": MODEL, "input": ["hi", "yo"]})).await;
+    let expected = json!({"model": MODEL, "input": [prompt_ids("hi"), prompt_ids("yo")]});
