+// The terminal finish reason — Python's `FinishReasonDict`
+// (`BaseFinishReason.to_json()` in schedule_batch.py), echoed verbatim as
+// `meta_info.finish_reason`. JSON is internally tagged by "type" with the
+// variant payload inlined; a type this build doesn't know round-trips
+// unchanged (unknown_variant_passthrough) so a Python-side addition never
+// fails a frame decode.
+
+syntax = "proto3";
+
+package sglang.api.v1;
+
+import "sglang/json/v1/options.proto";
+
+// Python's `matched` key, `Union[str, int, List[int]]`: the three wire shapes
+// are disjoint, so shape alone picks the arm (untagged).
+message Matched {
+  oneof value {
+    option (sglang.json.v1.oneof_json).shape = ONEOF_SHAPE_UNTAGGED;
+    int64 token = 1;
+    string str = 2;
+    MatchedTokens tokens = 3;
+  }
+}
+
+message MatchedTokens {
+  option (sglang.json.v1.message_json).shape = MESSAGE_SHAPE_BARE_LIST;
+  repeated int64 ids = 1;
+}
+
+// `FINISH_MATCHED_TOKEN` / `FINISH_MATCHED_STR` / `FINISHED_MATCHED_REGEX` —
+// all three report `type: "stop"`, matching the OpenAI API's value.
+message FinishStop {
+  optional Matched matched = 1;
+}
+
+// `FINISH_LENGTH` — hit `max_new_tokens` (or the context limit).
+message FinishLength {
+  optional uint64 length = 1;
+}
+
+// The `FINISH_ABORT` payload. Python emits all three keys, nulls included.
+message FinishAbort {
+  optional string message = 1 [(sglang.json.v1.field_json).emit_null_when_absent = true];
+  optional uint32 status_code = 2 [(sglang.json.v1.field_json).emit_null_when_absent = true];
+  optional string err_type = 3 [(sglang.json.v1.field_json).emit_null_when_absent = true];
+}
+
+message FinishReason {
+  oneof kind {
+    option (sglang.json.v1.oneof_json).shape = ONEOF_SHAPE_TAGGED;
+    option (sglang.json.v1.oneof_json).tag = "type";
+    option (sglang.json.v1.oneof_json).unknown_variant_passthrough = true;
+    FinishStop stop = 1;
+    FinishLength length = 2;
+    FinishAbort abort = 3;
+    // The passthrough arm: an unrecognized `type`, kept as its raw map
+    // (JSON text — Struct would coerce integer values to doubles).
+    string unknown = 4 [(sglang.json.v1.field_json).raw_json = true];
+  }
+}

@@ -0,0 +1,243 @@
+// The native `/generate` surface — the ground truth for
+// rust/sglang-server/src/message/request.rs's GenerateBody (request) and
+// api_core/frame.rs's frame shape (response). Unknown JSON keys on the
+// request are IGNORED: `deny_unknown_fields` broke real clients that send
+// Python-only `GenerateReqInput` fields (priority, extra_key, session_id,
+// ...), pinned by request.rs's unported-fields test.
+
+syntax = "proto3";
+
+package sglang.api.v1;
+
+import "sglang/api/v1/common.proto";
+import "sglang/api/v1/finish.proto";
+import "sglang/api/v1/sampling.proto";
+import "sglang/json/v1/options.proto";
+
+message GenerateRequest {
+  // (message_json).unknown_fields defaults to IGNORE — stated here as schema
+  // intent, load-bearing for client compat.
+
+  StringOrList rid = 1;
+  StringOrList text = 2;
+  TokenIdsOrList input_ids = 3;
+  optional bool stream = 4 [
+    (sglang.json.v1.field_json).null_policy = NULL_POLICY_RESETS_DEFAULT,
+    (sglang.json.v1.field_json).default_bool = false
+  ];
+  // One set of params, or one per batch item. JSON errors keep serde's
+  // field-level texts (the hand-written SamplingParamsInput contract).
+  SamplingParamsOrList sampling_params = 5;
+  BoolOrList return_logprob = 6;
+  Int64OrList logprob_start_len = 7;
+  Int64OrList top_logprobs_num = 8;
+  TokenIdsOrList token_ids_logprob = 9;
+  BoolOrList return_hidden_states = 10;
+  optional bool return_text_in_logprobs = 11;
+  // PD bootstrap columns: a batch mixes bootstrapped and plain requests, so
+  // elements are individually nullable.
+  OptionalStringOrList bootstrap_host = 12;
+  OptionalInt64OrList bootstrap_port = 13;
+  OptionalInt64OrList bootstrap_room = 14;
+  OptionalStringOrList bootstrap_pair_key = 15;
+  OptionalInt64OrList decode_tp_size = 16;
+  optional int64 routed_dp_rank = 17;
+  optional int64 disagg_prefill_dp_rank = 18;
+  // Multimodal payloads pass through untyped (data URIs, URLs, file paths, or
+  // nested batch lists) to the MM pipeline, which owns their validation.
+  // Media inputs, one container per modality (see MediaInput). The item
+  // hints a modality does not support are rejected at the processor.
+  optional MediaInput image_data = 19;
+  // Per-item content hashes overriding the computed ones, in item order; a
+  // flat list for one request (the batch form is rejected downstream).
+  optional StringListOrList mm_hashes = 20;
+  optional MediaInput video_data = 21;
+  optional MediaInput audio_data = 22;
+}
+
+message SamplingParamsOrList {
+  oneof value {
+    option (sglang.json.v1.oneof_json).shape = ONEOF_SHAPE_ONE_OR_MANY;
+    SamplingParams one = 1;
+    SamplingParamsList many = 2;
+  }
+}
+
+message SamplingParamsList {
+  option (sglang.json.v1.message_json).shape = MESSAGE_SHAPE_BARE_LIST;
+  repeated SamplingParams items = 1;
+}
+
+// One `[logprob, token_id, text|null]` entry (text present when
+// `return_text_in_logprobs`, decoded on the detok shard). The logprob slot is
+// optional: Python emits null for a position with no logprob (the first
+// prefill token; Rust maps the scheduler's NaN to the same null).
+message LogprobEntry {
+  option (sglang.json.v1.message_json).shape = MESSAGE_SHAPE_TUPLE;
+  optional double logprob = 1;
+  int64 token_id = 2;
+  optional string text = 3;
+}
+
+message LogprobEntries {
+  option (sglang.json.v1.message_json).shape = MESSAGE_SHAPE_BARE_LIST;
+  repeated LogprobEntry entries = 1;
+}
+
+// One decode position's top-k alternatives.
+message TopLogprobRow {
+  option (sglang.json.v1.message_json).shape = MESSAGE_SHAPE_BARE_LIST;
+  repeated LogprobEntry entries = 1;
+}
+
+// A position's row, or null: a position that recorded no alternatives is
+// null on the wire (Python parity), never [].
+message NullableTopLogprobs {
+  option (sglang.json.v1.message_json).shape = MESSAGE_SHAPE_TRANSPARENT;
+  TopLogprobRow row = 1;
+}
+
+message HiddenStateRow {
+  option (sglang.json.v1.message_json).shape = MESSAGE_SHAPE_BARE_LIST;
+  repeated double values = 1;
+}
+
+message GenerateMetaInfo {
+  // The client's rid, byte-for-byte (`Rid::client_facing`).
+  string id = 1;
+  uint32 prompt_tokens = 2;
+  uint64 completion_tokens = 3;
+  // Always present in JSON, null until a terminal frame.
+  FinishReason finish_reason = 4 [(sglang.json.v1.field_json).emit_null_when_absent = true];
+  // input+output token logprobs are set together, empty lists included: a PD
+  // decode node never receives input logprobs, but the PD router keys its
+  // merge of prefill's on the key's presence.
+  LogprobEntries output_token_logprobs = 5;
+  LogprobEntries input_token_logprobs = 6;
+  repeated NullableTopLogprobs output_top_logprobs = 7;
+  repeated NullableTopLogprobs input_top_logprobs = 8;
+  repeated NullableTopLogprobs output_token_ids_logprobs = 9;
+  repeated NullableTopLogprobs input_token_ids_logprobs = 10;
+  repeated HiddenStateRow hidden_states = 11;
+  // Seconds from normalized-request acceptance to the terminal output; only
+  // on the terminal frame.
+  optional double e2e_latency = 12;
+}
+
+message GenerateResponse {
+  // JSON key order is FIELD-NUMBER order: text, meta_info, then the
+  // conditionally-present output_ids and index — matching frame_value's
+  // insertion order byte-for-byte.
+  string text = 1;
+  GenerateMetaInfo meta_info = 2;
+  // Omitted while empty (a text-only frame).
+  TokenIds output_ids = 3;
+  // Batch position; only on batch responses/frames.
+  optional uint32 index = 4;
+}
+
+// One request's failure inside a Generate stream; carries its batch position
+// (the HTTP SSE shape puts `index` beside the error object the same way).
+message GenerateStreamError {
+  ErrorBody error = 1;
+  optional uint32 index = 2;
+}
+
+// One item of the gRPC Generate stream: a frame, or one request's failure
+// (the stream continues — other batch items may still be running). On HTTP
+// the same failure is an in-stream SSE error frame.
+message GenerateStreamItem {
+  oneof item {
+    GenerateResponse frame = 1;
+    GenerateStreamError error = 2;
+  }
+}
+
+// ---- Media inputs ----------------------------------------------------------
+//
+// Every form Python's `/generate` accepts, typed. Preprocessed inputs
+// (`format: "processor_output"` / `"precomputed_embedding"`) are NOT part of
+// the HTTP contract: their values are tensors, which JSON cannot carry; they
+// exist for the in-process Engine only.
+
+// One media item's source and per-item hints. Unknown keys are an error: a
+// hint this schema does not name would otherwise be silently dropped.
+message MediaRef {
+  option (sglang.json.v1.message_json).unknown_fields = UNKNOWN_FIELDS_DENY;
+  // URL, `file://` / absolute path, `data:` URI, or bare base64.
+  string url = 1;
+  // Image: "auto" | "low" | "high" (the OpenAI detail hint).
+  optional string detail = 2;
+  // Image/video: dynamic-patch budget (InternVL-style processors).
+  optional int64 max_dynamic_patch = 3;
+  // Image: a caller-supplied content hash that overrides the computed one.
+  optional string content_hash = 4;
+  // Video/image budgets read by the GLM and MiMo processors.
+  optional int64 min_pixels = 5;
+  optional int64 max_pixels = 6;
+  optional int64 total_max_pixels = 7;
+  optional double fps = 8;
+  optional int64 num_frames = 9;
+  optional int64 min_frames = 10;
+  optional int64 max_frames = 11;
+  optional int64 max_tokens_per_frame = 12;
+  optional int64 max_image_tokens = 13;
+  // Video: also decode the audio track.
+  optional bool use_audio = 14;
+  // GLM-Image external AR uses grids with input_ids to compute MRoPE positions.
+  optional ImageGridThw image_grid_thw = 15;
+}
+
+// One (t, h, w) row per image; the processor validates row arity.
+message ImageGridThw {
+  option (sglang.json.v1.message_json).shape = MESSAGE_SHAPE_BARE_LIST;
+  repeated Int64List rows = 1;
+}
+
+// One media item. JSON: a bare string is the source; an object is a MediaRef.
+message MediaItem {
+  oneof value {
+    option (sglang.json.v1.oneof_json).shape = ONEOF_SHAPE_UNTAGGED;
+    string source = 1;
+    MediaRef ref = 2;
+  }
+}
+
+// A list element that may be JSON null (Python's `[img, None]`).
+message OptionalMediaItem {
+  option (sglang.json.v1.message_json).shape = MESSAGE_SHAPE_TRANSPARENT;
+  optional MediaItem item = 1;
+}
+
+// One request's items (`[a, null, b]`), or one batch entry's items.
+message MediaItems {
+  option (sglang.json.v1.message_json).shape = MESSAGE_SHAPE_BARE_LIST;
+  repeated OptionalMediaItem items = 1;
+}
+
+// A batch entry whose item list may be JSON null.
+message OptionalMediaItems {
+  option (sglang.json.v1.message_json).shape = MESSAGE_SHAPE_TRANSPARENT;
+  optional MediaItems items = 1;
+}
+
+// One item list per batch entry (`[[a, b], null, []]`).
+message MediaItemsList {
+  option (sglang.json.v1.message_json).shape = MESSAGE_SHAPE_BARE_LIST;
+  repeated OptionalMediaItems items = 1;
+}
+
+// The three container forms Python's `_normalize_image_data` distinguishes.
+// JSON: a string or object is `item` (one item; a broadcast in a batch); an
+// array whose first element is not an array is `many` (a flat list; `[]` is
+// an empty `many`); an array whose first element is an array is `nested`
+// (one list per batch entry). Which forms a request may use depends on
+// whether it is a batch, and is checked downstream, not here.
+message MediaInput {
+  oneof value {
+    option (sglang.json.v1.oneof_json).shape = ONEOF_SHAPE_UNTAGGED;
+    MediaItem item = 1;
+    MediaItems many = 2;
+    MediaItemsList nested = 3;
+  }
+}

