+// The JSON-fidelity option vocabulary: how a message, field, or oneof behaves
+// on the HTTP JSON wire, declared in the schema itself. The sglang-api-codegen
+// generator reads these options from the FileDescriptorSet and emits the serde
+// implementations; proto3's canonical JSON mapping is NOT used. Each option is
+// one generator template with its own unit tests.
+//
+// gRPC never sees these options: the protobuf wire format is untouched.
+
+syntax = "proto3";
+
+package sglang.json.v1;
+
+import "google/protobuf/descriptor.proto";
+
+// How a message treats unknown JSON keys on deserialization.
+enum UnknownFields {
+  // Silently dropped (the default): parity with endpoints that accept and
+  // ignore unported fields, where rejecting would break existing clients.
+  UNKNOWN_FIELDS_IGNORE = 0;
+  // A 400 with serde's field-level message: parity with Python constructors
+  // that TypeError on unexpected kwargs.
+  UNKNOWN_FIELDS_DENY = 1;
+}
+
+// How a message is shaped on the JSON wire. One shape per message: an enum,
+// not independent flags, so two cannot be set at once.
+enum MessageShape {
+  // A plain JSON object keyed by field name (the default).
+  MESSAGE_SHAPE_OBJECT = 0;
+
+  // A single-`repeated`-field carrier (TokenIds, StringList, ...): its JSON
+  // is the bare array, not an {items: [...]} object, wherever it appears.
+  MESSAGE_SHAPE_BARE_LIST = 1;
+
+  // A positional tuple: the fields, in declaration order, form a bare array
+  // (e.g. a logprob entry's [logprob, token_id, text|null]). Optional members
+  // serialize as null.
+  MESSAGE_SHAPE_TUPLE = 2;
+
+  // A single-field message that is invisible in JSON: it serializes as its
+  // sole field's value (null when unset). Exists to give proto a presence
+  // wrapper for nullable LIST ELEMENTS (OptionalString, OptionalInt64).
+  MESSAGE_SHAPE_TRANSPARENT = 3;
+}
+
+// Attached to a message: `option (sglang.json.v1.message_json).<name> = ...;`
+// in its body. Decides the JSON form of the message as a whole, for both
+// directions of the HTTP wire: `shape` says what the serializer writes and
+// what the deserializer expects (object, bare array, tuple, or the sole
+// field's value); `unknown_fields` says what the deserializer does with keys
+// the message does not declare. Serialization never emits unknown keys.
+message MessageJson {
+  UnknownFields unknown_fields = 1;
+  MessageShape shape = 2;
+}
+
+// How an absent key or an explicit JSON null reads into a field. One policy
+// per field: an enum, not independent flags, so two cannot be set at once.
+// Deserialization only; `emit_null_when_absent` is the serialization side.
+enum NullPolicy {
+  // Absent is unset; an explicit null is a type error (the default).
+  NULL_POLICY_DEFAULT = 0;
+
+  // Explicit null (and an absent key) yields the stated default instead of
+  // an error: parity with Python dataclasses whose __post_init__ maps None
+  // back to the default.
+  NULL_POLICY_RESETS_DEFAULT = 1;
+
+  // An ABSENT key yields the stated default, but an explicit null clears the
+  // field to no-value (e.g. max_new_tokens: absent = 128, null = no limit).
+  NULL_POLICY_IS_NONE = 2;
+}
+
+// Attached to one field: `type name = N [(sglang.json.v1.field_json).<name>
+// = ...];`. Decides how that key behaves, with the read and write sides kept
+// apart. Deserialization: `null_policy` (with a `default_*`) maps an absent
+// key or an explicit null onto a value. Serialization: `emit_null_when_absent`
+// writes the key as null instead of omitting it. Both directions: `raw_json`
+// carries the value through as JSON text, and `int_key_map` spells numeric
+// map keys as strings.
+message FieldJson {
+  NullPolicy null_policy = 1;
+  // The default a non-DEFAULT policy yields; exactly one must accompany it.
+  optional double default_f64 = 2;
+  optional int64 default_i64 = 3;
+  optional bool default_bool = 4;
+  optional string default_string = 5;
+
+  // The key is always serialized, an unset value as an explicit null (e.g.
+  // reasoning_content in chat deltas: Python always emits the key).
+  bool emit_null_when_absent = 6;
+
+  // On a string (or repeated string) field: the string holds JSON text, and
+  // HTTP (de)serialization passes the VALUE through — integers, nesting, and
+  // element shapes intact (google.protobuf.Struct cannot do this: it coerces
+  // integers to doubles). gRPC carries the JSON text.
+  bool raw_json = 7;
+
+  // On a map<string, ...> field whose keys are numeric strings (Python
+  // parity, e.g. logit_bias token ids).
+  bool int_key_map = 8;
+}
+
+// How a oneof (a union) is spelled on the JSON wire. One shape per union.
+enum OneofShape {
+  // Unset: the message owning the oneof is a plain object.
+  ONEOF_SHAPE_UNSPECIFIED = 0;
+
+  // Untagged: the value's shape picks the variant, and variant mismatch
+  // errors keep serde's field-level texts (never "data did not match any
+  // variant").
+  ONEOF_SHAPE_UNTAGGED = 1;
+
+  // On a oneof of exactly { T one; TList many; }: a JSON scalar deserializes
+  // as `one`, a JSON array as `many`; serialization flattens the same way.
+  ONEOF_SHAPE_ONE_OR_MANY = 2;
+
+  // Internally tagged by the key in `tag` (e.g. finish_reason's
+  // {"type": "stop", ...}); variant payload fields inline into the same
+  // object, with each variant's tag value being its field name.
+  ONEOF_SHAPE_TAGGED = 3;
+}
+
+// Attached to a oneof: `option (sglang.json.v1.oneof_json).<name> = ...;` in
+// its body. A oneof is a tagged union on the protobuf wire (the field number
+// is the tag); JSON has no such tag, so `shape` picks how the union is
+// spelled there and how the deserializer recovers the variant: by value
+// shape (untagged), scalar versus array (one_or_many), or a discriminator key
+// named by `tag` (tagged). `unknown_variant_passthrough` lets a tagged union
+// round-trip a variant this schema does not know.
+message OneofJson {
+  OneofShape shape = 1;
+
+  // The discriminator key; required with ONEOF_SHAPE_TAGGED, meaningless
+  // otherwise.
+  string tag = 2;
+
+  // With ONEOF_SHAPE_TAGGED: JSON input matching no variant is captured
+  // verbatim by the designated catch-all variant (a raw_json Struct member)
+  // and round-trips unchanged -- the forward-compatibility escape hatch for
+  // values another component may extend (e.g. finish_reason).
+  bool unknown_variant_passthrough = 3;
+}
+
+extend google.protobuf.MessageOptions {
+  // Field numbers from the internal-use extension range (50000-99999).
+  MessageJson message_json = 50100;
+}
+
+extend google.protobuf.FieldOptions {
+  FieldJson field_json = 50100;
+}
+
+extend google.protobuf.OneofOptions {
+  OneofJson oneof_json = 50100;
+}

@@ -0,0 +1,378 @@
+syntax = "proto3";
+package sglang.runtime.v1;
+
+import "google/protobuf/struct.proto";
+
+service SglangService {
+  // SGLang-native RPCs (typed proto)
+  rpc TextGenerate(TextGenerateRequest) returns (stream TextGenerateResponse);
+  rpc Generate(GenerateRequest) returns (stream GenerateResponse);
+  rpc TextEmbed(TextEmbedRequest) returns (TextEmbedResponse);
+  rpc Embed(EmbedRequest) returns (EmbedResponse);
+  rpc Classify(ClassifyRequest) returns (ClassifyResponse);
+  rpc Tokenize(TokenizeRequest) returns (TokenizeResponse);
+  rpc Detokenize(DetokenizeRequest) returns (DetokenizeResponse);
+  rpc HealthCheck(HealthCheckRequest) returns (HealthCheckResponse);
+  rpc WatchEngineState(WatchEngineStateRequest) returns (stream EngineStateSnapshot);
+  rpc GetModelInfo(GetModelInfoRequest) returns (GetModelInfoResponse);
+  rpc GetServerInfo(GetServerInfoRequest) returns (GetServerInfoResponse);
+  rpc ListModels(ListModelsRequest) returns (ListModelsResponse);
+  rpc GetLoad(GetLoadRequest) returns (GetLoadResponse);
+  rpc Abort(AbortRequest) returns (AbortResponse);
+  rpc FlushCache(FlushCacheRequest) returns (FlushCacheResponse);
+  rpc PauseGeneration(PauseGenerationRequest) returns (PauseGenerationResponse);
+  rpc ContinueGeneration(ContinueGenerationRequest) returns (ContinueGenerationResponse);
+
+  // OpenAI-compatible RPCs (JSON pass-through)
+  rpc ChatComplete(OpenAIRequest) returns (stream OpenAIStreamChunk);
+  rpc Complete(OpenAIRequest) returns (stream OpenAIStreamChunk);
+  rpc OpenAIEmbed(OpenAIRequest) returns (OpenAIResponse);
+  rpc OpenAIClassify(OpenAIRequest) returns (OpenAIResponse);
+  rpc Score(OpenAIRequest) returns (OpenAIResponse);
+  rpc Rerank(OpenAIRequest) returns (OpenAIResponse);
+
+  // Admin/Ops RPCs
+  rpc StartProfile(StartProfileRequest) returns (StartProfileResponse);
+  rpc StopProfile(StopProfileRequest) returns (StopProfileResponse);
+  rpc UpdateWeightsFromDisk(UpdateWeightsRequest) returns (UpdateWeightsResponse);
+}
+
+// Disaggregated prefill/decode rendezvous parameters.
+//
+// Carried on Generate/TextGenerate requests when the worker is part of a
+// disaggregated deployment. The prefill leg writes its KV cache to the
+// bootstrap server identified by (bootstrap_host, bootstrap_port) under
+// the room id; the decode leg fetches it from the same room. Both legs
+// receive the same `bootstrap_room` from the router so they rendezvous
+// on the KV transfer.
+message DisaggregatedParams {
+  string bootstrap_host = 1;
+  int32 bootstrap_port = 2;
+  int64 bootstrap_room = 3;
+}
+
+// Sampling parameters shared across text and tokenized RPCs.
+message SamplingParams {
+  optional float temperature = 1;
+  optional float top_p = 2;
+  optional int32 top_k = 3;
+  optional float min_p = 4;
+  optional float frequency_penalty = 5;
+  optional float presence_penalty = 6;
+  optional float repetition_penalty = 7;
+  optional int32 max_new_tokens = 8;
+  optional int32 min_new_tokens = 9;
+  repeated string stop = 10;
+  repeated int32 stop_token_ids = 11;
+  optional bool ignore_eos = 12;
+  optional int32 n = 13;
+  optional string json_schema = 14 [deprecated = true];
+  optional string regex = 15 [deprecated = true];
+  optional int64 seed = 16;
+  optional GuidedDecoding guided_decoding = 17;
+}
+
+message GuidedDecoding {
+  oneof constraint {
+    string json_schema = 1;
+    string regex = 2;
+    string ebnf = 3;
+    ChoiceConstraint choice = 4;
+    string structural_tag = 5;
+  }
+}
+
+message ChoiceConstraint {
+  repeated string values = 1;
+}
+
