+        out.data_ptr<scalar_t>(),
+        x,
+        w13.data_ptr<int8_t>(),
+        w2.data_ptr<int8_t>(),
+        x_scale,
+        w13s.data_ptr<float>(),
+        w2s.data_ptr<float>(),
+        x_per_expert,
+        M,
+        N,
+        K,
+        E,
