+          memcpy(buf1, a_rows[i + 1] + k, (K - k) * sizeof(int8_t));
+          const int64x2_t va0_s64 = vreinterpretq_s64_s8(vld1q_s8(buf0));
+          const int64x2_t va1_s64 = vreinterpretq_s64_s8(vld1q_s8(buf1));
