+        for (int i = 0; i < R / 2; ++i) {
+          for (int j = 0; j < C / 2; ++j) {
+            vsums[i][j] = vmmlaq_s32(vsums[i][j], va[i * 2 + 0], vb[j * 2 + 0]);
+            vsums[i][j] = vmmlaq_s32(vsums[i][j], va[i * 2 + 1], vb[j * 2 + 1]);
