+template <>
+inline void
+quantize_row_int8<at::BFloat16>(int8_t* __restrict__ q, float* scale, const at::BFloat16* __restrict__ x, int64_t n) {
+  quantize_row_int8(q, scale, reinterpret_cast<const bfloat16_t*>(x), n);
