+    const float32x4_t vf32 = vld1q_f32(f32 + i);
+    const bfloat16x4_t vbf16 = vcvt_bf16_f32(vf32);
+    vst1_bf16(bf16 + i, vbf16);
+  }
+
+  for (; i < n; ++i) {
+    bf16[i] = vcvth_bf16_f32(f32[i]);
+  }
