+  uint32_t f32 = __float_as_uint(val);
+  uint8_t sign = static_cast<uint8_t>((f32 >> 24) & 0x80u);
+  f32 &= 0x7FFFFFFFu;
+
+  int32_t exp32 = static_cast<int32_t>((f32 >> 23) & 0xFFu);
+  uint32_t mant32 = f32 & 0x7FFFFFu;
