+  uint32_t mant3 = (mant32 >> 20) & 0x7u;
+  uint32_t rbit = (mant32 >> 19) & 1u;
+  uint32_t sbit = (mant32 & 0x7FFFFu) != 0;
+  mant3 += (rbit && (sbit || (mant3 & 1u)));
