+  using Traits = QKernelTraits<kHeadDim, kRopeDim>;
+  constexpr int64_t kVecSize = Traits::kVecSize;
+  constexpr int64_t kLocalSize = Traits::kLocalSize;
+  constexpr uint32_t kRopeSize = Traits::kRopeSize;
