+    } else if (dst_type == at::ScalarType::Float8_e4m3fn) {
+      LAUNCH_KERNEL_OUTER(scalar_t, c10::Float8_e4m3fn);
+      return true;
+    }
+    return false;
+  });
+
+#undef LAUNCH_KERNEL
+#undef LAUNCH_KERNEL_INNER
+}

