+  }
+
+  const int blocks_per_tile_x_row = WARP_SIZE_GGUF / QI8_0;
+  const int kbxd = k % blocks_per_tile_x_row;
+
+#pragma unroll
+  for (int i0 = 0; i0 < mmq_y; i0 += nwarps * QI8_0) {
