+// Fused QSA (Qwen4-Exp sparse attention) indexer-prep kernels.
+// Outputs are bit-identical to the eager bf16/fp16 aten chain, mirrored step by step.
+
+#include <sgl_kernel/tensor.h>
+#include <sgl_kernel/utils.h>
