+    if (is_cluster && cfg.cooperative) {
+        KU_ASSERT(false, "cluster and cooperative launch are mutually exclusive");
+    }
+
+    if (cfg.cooperative) {
+        void* kernel_args[sizeof...(Args) > 0 ? sizeof...(Args) : 1] = {};
