+  // part 1: LayerNorm
+  {
+    Storage input_vec;
+    input_vec.load(input_ptr, lane_id);
+    gamma.load(params.weight, lane_id);
+    beta.load(params.bias, lane_id);
+    if (is_rope_lane) freq = load_rope_first_cos_sin<kRopeDim>(cos_sin_cache, lane_id);
