+        static_cast<uint32_t>(div_ceil(max_keys, static_cast<int64_t>(C::kKeysPerCTA))));
+    LaunchKernel(grid, C::kBlockSize, device_.unwrap())
+        .config({.use_pdl = kPDL})
+        .launch(amax8_varlen_kernel<kPDL>, params);
+  }
+};
+
+}  // namespace sglang

