+      Tensor out = ffi::empty_like(in);
+      const auto params = PushParams{
+          .input = in.data_ptr(),
+          .output = out.data_ptr(),
+          .num_vecs = num_vecs,
+          .rank = push.rank,
+          .ws = push.get_workspace<kWorldSize>(nbytes),
