+template <typename T>
+__global__ void clamp_position_kernel(T* __restrict__ dst, const T* __restrict__ seq_lens, size_t n) {
+  size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
+  if (idx < n) {
+    T val = seq_lens[idx] - 1;
+    dst[idx] = val < 0 ? 0 : val;
