+    const DLDevice device = device_.unwrap();
+
+    LaunchKernel(grid_size, kBlockSize, device)(
+        clamp_position_kernel<T>,
+        static_cast<T*>(dst.data_ptr()),
+        static_cast<const T*>(seq_lens.data_ptr()),
+        num_elements);
+  }
+};
