+// ---------------------------------------------------------------------------
+// Host-side tvm-ffi entry point
+// ---------------------------------------------------------------------------
+
+void fused_qk_norm_rope(
+    tvm::ffi::TensorView qkv,           // [num_tokens, (nq+nk+nv)*head_dim] bf16
+    tvm::ffi::TensorView q_weight,      // [head_dim] bf16
+    tvm::ffi::TensorView k_weight,      // [head_dim] bf16
