+
+// ---------------------------------------------------------------------------
+// CTA launcher: validates tensors, launches one block per row.
+// ---------------------------------------------------------------------------
+template <int64_t kDim, bool kUsePDL, typename DType>
+struct HFRMSNormKernel {
+  static_assert(sizeof(DType) == 2, "rmsnorm_hf: DType must be fp16_t or bf16_t");
