+  constexpr int64_t kCosSinStrideBytes = kRopeDim * sizeof(float);
+  constexpr int64_t kVecSize = kRopeDim / (2 * kWorkThreads * (1 + kIsNeox));
+  constexpr int64_t kDimPerThread = kVecSize * 2 * (1 + kIsNeox);
