+        aligned(q_nope.data_ptr(), 16) && (S0_qn.unwrap() * kDtypeSize) % 16 == 0 &&
+        (S1_qn.unwrap() * kDtypeSize) % 16 == 0)
+        << "q_nope base/strides must be 16-byte aligned";
+    CHECK_HOST(
+        aligned(q_rope.data_ptr(), 4) && (S0_qr.unwrap() * kDtypeSize) % 4 == 0 &&
