+  TensorMatcher({B, Mrow})  //
+      .with_strides({-1, 1})
+      .with_dtype(dtype)
+      .with_device(device)
+      .verify(k)
+      .verify(v);
+  TensorMatcher({-1, Mrow})  //
+      .with_strides({-1, 1})
+      .with_dtype(dtype)
+      .with_device(device)
+      .verify(k_cache)
+      .verify(v_cache);
+  TensorMatcher({B, Drow})  //
+      .with_strides({-1, 1})
+      .with_dtype(dtype)
+      .with_device(device)
+      .verify(idx_k)
+      .verify(idx_v);
