+          b,
+          sfa,
+          sfb,
+          expert_offsets,
+          blockscale_offsets,
+          tokens_per_expert,
+          b_ptrs,
+          sfb_ptrs,
+          d,
+          d_ptrs,
+          workspace,
+          static_cast<int>(num_experts.unwrap()),
+          static_cast<int>(M.unwrap()),
+          static_cast<int>(num_tokens.unwrap()),
+          static_cast<int>(K.unwrap()),
+          device_id,
+          static_cast<int>(runtime::get_sm_count(device_id)),
+          stream);
+    } else {
+      Panic("Unsupported dtype");
+    }
+  }
