+  CHECK_DEVICE(sorted_topk_ids, expert_offsets);
+  CHECK_DEVICE(sorted_topk_ids, src2dst);
+  CHECK_DIM(1, sorted_topk_ids);
+  CHECK_DIM(1, reorder_ids);
+  CHECK_DIM(1, expert_offsets);
+  CHECK_DIM(1, src2dst);
