+// ---------------------------------------------------------------------------
+// Aligned array — avoids CUTLASS dependency; identical semantics.
+// ---------------------------------------------------------------------------
+template <typename T, int N, int Alignment = static_cast<int>(sizeof(T) * N)>
+class alignas(Alignment) AlignedArray {
+  T data[N];
+};
