+template <typename T, int EXPERTS, int WARPS_PER_TB>
+void topkGatingSoftmaxLauncherHelper(
+    const T* input,
+    const bool* finished,
+    float* output,
+    int* indices,
+    const int num_rows,
+    const int k,
+    const int start_expert,
+    const int end_expert,
+    const bool renormalize,
+    const float moe_softcapping,
