+        q,
+        q_cos,
+        q_sin,
+        q_weight,
+        q_out,
+        static_cast<float>(eps),
+        batch_size * q_seq_len.unwrap(),
+        q_seq_len.unwrap(),
+        num_heads,
+        head_dim,
+        q_cos.stride(0),
+        q_cos.stride(1),
+        q_cos.stride(2),
+        q_sin.stride(0),
+        q_sin.stride(1),
+        q_sin.stride(2),
+        dl_device);
+    launch_one<kRoundIntermediates>(
+        k,
+        k_cos,
+        k_sin,
+        k_weight,
+        k_out,
+        static_cast<float>(eps),
+        batch_size * k_seq_len.unwrap(),
+        k_seq_len.unwrap(),
+        num_heads,
+        head_dim,
+        k_cos.stride(0),
+        k_cos.stride(1),
+        k_cos.stride(2),
+        k_sin.stride(0),
+        k_sin.stride(1),
