+inline int32_t computeLog2(int32_t val, std::string const &name = "") {
+  int32_t n = val;
+  int32_t out = 0;
+  while (n >>= 1) {
+    ++out;
+  }
+  if ((1 << out) != val) {
+    out = -1;
+  }
+  return out;
+}
