+void Runner::run(void *hiddenState, void *hiddenStateScale, void *weights,
+                 void *weightsScale, void *perTokenScales,
+                 void *perChannelScales, float *outputScalesScalar,
+                 float *outputScalesGateScalar, float *ptrBias, float *ptrAlpha,
+                 float *ptrBeta, float *ptrClampLimit, void *output,
+                 void *outputScale, int32_t topK, int32_t hiddenSize,
+                 int32_t intermediateSize, int32_t numExperts,
+                 int32_t numTokens, int32_t *permutedIdxToTokenIdx,
+                 int32_t *ptrNumNonExitingCtas,
+                 int32_t *ptrTotalNumPaddedTokens,
+                 int32_t *ptrCtaIdxXyToBatchIdx, int32_t *ptrCtaIdxXyToMnLimit,
+                 void *bmm1Workspace, bool useRoutingScalesOnInput, int device,
+                 cudaStream_t stream, int32_t configIndex, bool enable_pdl) {
+  auto maxNumCtasInBatchDim = Routing::getMaxNumCtasInBatchDim(
+      numTokens, topK, numExperts, mTileTokensDim);
+  int32_t intermediateSizeFactor = (isGatedActivation(mActType) ? 2 : 1);
+  mRunner.run(numTokens, intermediateSizeFactor * intermediateSize, hiddenSize,
+              {}, numTokens, numExperts, maxNumCtasInBatchDim, hiddenState,
+              hiddenStateScale, weights, weightsScale, perTokenScales,
+              perChannelScales, outputScalesScalar, outputScalesGateScalar,
+              ptrBias, ptrAlpha, ptrBeta, ptrClampLimit, output, outputScale,
+              permutedIdxToTokenIdx, ptrTotalNumPaddedTokens,
+              ptrCtaIdxXyToBatchIdx, ptrCtaIdxXyToMnLimit, ptrNumNonExitingCtas,
+#if SGLANG_FLASHINFER_HAS_PERMUTED_BIAS_ROW_IDX
+              /* permutedIdxToBiasRowIdx */ nullptr,
+#endif
+              bmm1Workspace, stream, device, configIndex, enable_pdl);
