+void Runner::setOpsData(MoERunnerArgs const &args,
+                        MoEWorkspace const &workspace,
+                        moe::dev::convertsf::Data &convertSfData,
+                        moe::dev::activation::Data &activationData,
+                        moe::dev::finalize::Data &finalizeData) {
+  // Setup sf conversion data if needed
+  convertSfData.inSfPtr = args.hidden_states_scale;
+  convertSfData.outSfPtr = workspace.hidden_states_scale_linear;
+  convertSfData.hiddenDimSf = args.hidden_size / 16;
+  convertSfData.numTokens = args.num_tokens;
+  convertSfData.sfLayoutSrc = btg::SfLayout::R128c4;
+  convertSfData.sfLayoutDst = btg::SfLayout::Linear;
+  convertSfData.mUsePdl = true;
+
+  // Setup activation data
+  activationData.mDtypeElt = args.mDtypeElt;
+  activationData.mUsePdl = true;
+  activationData.mUseDeepSeekFp8 = true;
+  activationData.inPtr = workspace.gemm1_output;
+  activationData.outPtr = workspace.activation_output;
+  activationData.inDqSfsPtr = workspace.gemm1_output_scale;
+  activationData.outDqSfsPtr = workspace.activation_output_scale;
+  activationData.gateUpLoraDeltaPtr =
+      reinterpret_cast<cutlass::bfloat16_t const *>(args.gate_up_lora_delta);
+  activationData.activationLoraInputOutPtr =
+      reinterpret_cast<cutlass::bfloat16_t *>(args.activation_lora_input);
+  activationData.innerDim = args.intermediate_size *
+                            (isGatedActivation(args.activation_type) ? 2 : 1);
+  activationData.topK = args.top_k;
+  activationData.numTokens = args.num_tokens;
+  activationData.expandedIdxToPermutedIdx =
+      workspace.expanded_idx_to_permuted_idx;
+
+  activationData.totalNumPaddedTokens = workspace.total_num_padded_tokens;
+
+  // Setup finalize data
+  if (args.do_finalize) {
+    // Setup finalize data
+    finalizeData.mDtypeElt = args.mDtypeOut;
+    finalizeData.mDtypeExpW = args.mDtypeExpW;
+    finalizeData.mUsePdl = true;
+    finalizeData.mUseDeepSeekFp8 = false;
+    finalizeData.inPtr = workspace.gemm2_output;
+    finalizeData.outPtr = args.output;
+    finalizeData.inDqSfsPtr = workspace.gemm2_output_scale;
+    finalizeData.outDqSfsPtr = args.output_scale;
+    if (args.mUseRoutingScalesOnInput) {
+      finalizeData.expertWeightsPtr = nullptr;
+    } else {
+      finalizeData.expertWeightsPtr = workspace.expert_weights;
+    }
+    finalizeData.expandedIdxToPermutedIdx =
+        workspace.expanded_idx_to_permuted_idx;
+    finalizeData.numTokens = args.num_tokens;
+    finalizeData.numExperts = args.num_experts;
+    finalizeData.topK = args.top_k;
+    // We want to fuse unpadding into the finalize kernel, so we need to use the
+    // output hidden size.
+    finalizeData.hiddenDim = args.hidden_size_output.value_or(args.hidden_size);
+    finalizeData.hiddenDimPadded = args.hidden_size;
+    finalizeData.totalNumPaddedTokens = workspace.total_num_padded_tokens;
+  }
+}
+
+std::tuple<int32_t, int32_t>
+Runner::getWorkspaceSizeInBytes(MoERunnerArgs const &args,
+                                int64_t configIndex) const {
+  FLASHINFER_CHECK(
+      configIndex >= 0 &&
+          configIndex < static_cast<int64_t>(mPassingConfigs.size()),
+      "Invalid MoE config index ", configIndex, ", valid range is [0, ",
+      static_cast<int64_t>(mPassingConfigs.size()) - 1, "].");
+  auto const &config = mPassingConfigs[configIndex];
+
+  auto workspace_size_fc1 =
+      static_cast<int32_t>(mPermuteGemm1.getWorkspaceSizeInBytes(
+          args.top_k, args.hidden_size, args.intermediate_size,
+          args.local_num_experts, args.num_tokens, config.gemm1Config));
+  auto workspace_size_fc2 = static_cast<int32_t>(mGemm2.getWorkspaceSizeInBytes(
+      args.top_k, args.hidden_size, args.intermediate_size,
+      args.local_num_experts, args.num_tokens, config.gemm2Config));
+  return std::make_tuple(workspace_size_fc1, workspace_size_fc2);
+}
+
+std::vector<int64_t> Runner::getValidConfigIndices(int32_t topK,
+                                                   int32_t hiddenSize,
+                                                   int32_t intermediateSize,
+                                                   int32_t numLocalExperts,
+                                                   int32_t numTokens) const {
+  std::vector<int64_t> validIndices;
+
+  for (int i = 0; i < mPassingConfigs.size(); ++i) {
+    auto const &config = mPassingConfigs[i];
+
+    if (mPermuteGemm1.isValidConfigIndex(config.gemm1Config, topK, hiddenSize,
+                                         intermediateSize, numLocalExperts,
+                                         numTokens) &&
+        mGemm2.isValidConfigIndex(config.gemm2Config, topK, hiddenSize,
+                                  intermediateSize, numLocalExperts,
+                                  numTokens)) {
+      validIndices.push_back(i);
+    }
+  }
+
+  return validIndices;
+}
+
+int64_t Runner::getDefaultValidConfigIndex(int32_t topK, int32_t hiddenSize,
+                                           int32_t intermediateSize,
+                                           int32_t numLocalExperts,
+                                           int32_t numTokens) const {
+  int32_t indexGemm1 = mPermuteGemm1.getDefaultValidConfigIndex(
+      topK, hiddenSize, intermediateSize, numLocalExperts, numTokens);
+  int32_t indexGemm2 = mGemm2.getDefaultValidConfigIndex(
+      topK, hiddenSize, intermediateSize, numLocalExperts, numTokens);
+
+  auto it = std::find_if(mPassingConfigs.begin(), mPassingConfigs.end(),
+                         [indexGemm1, indexGemm2](MoEConfig cfg) {
+                           return (cfg.gemm1Config == indexGemm1 &&
+                                   cfg.gemm2Config == indexGemm2);
+                         });
+  FLASHINFER_CHECK(
+      it != mPassingConfigs.end(),
+      "No compatible configs found for the block scale MoE runner.");
+  return std::distance(mPassingConfigs.begin(), it);
+}
+
+void Runner::run(MoERunnerArgs const &args, MoEWorkspace const &workspace,
+                 int device, cudaStream_t stream, int64_t configIndex,
+                 bool enable_pdl) {
+  FLASHINFER_CHECK(
+      configIndex >= 0 &&
+          configIndex < static_cast<int64_t>(mPassingConfigs.size()),
+      "Invalid MoE config index ", configIndex, ", valid range is [0, ",
+      static_cast<int64_t>(mPassingConfigs.size()) - 1, "].");
+  FLASHINFER_CHECK(!mUsePerChannelScalingGemm1 && !mUsePerChannelScalingGemm2,
+                   "Per-channel scaling is currently not supported.");
+  // Setup all operation data
+  moe::dev::activation::Data activationData;
+  moe::dev::finalize::Data finalizeData;
+  moe::dev::convertsf::Data convertSfData;
+  sync_check_cuda_error(stream);
+  setOpsData(args, workspace, convertSfData, activationData, finalizeData);
+
+  void *hidden_states_scale_linear{args.hidden_states_scale};
+
+  auto const &config = mPassingConfigs[configIndex];
+
+  mPermuteGemm1.run(
+      args.hidden_states, hidden_states_scale_linear, args.gemm1_weights,
+      args.gemm1_weights_scale, workspace.token_scales,
+      /*perChannelScales*/ nullptr, args.output1_scales_scalar,
+      args.output1_scales_gate_scalar, args.gemm1_bias, args.gemm1_alpha,
+      args.gemm1_beta, args.gemm1_clamp_limit, workspace.gemm1_output,
+      workspace.gemm1_output_scale, args.top_k, args.hidden_size,
+      args.intermediate_size, args.local_num_experts, args.num_tokens,
+      workspace.permuted_idx_to_token_idx, workspace.num_non_exiting_ctas,
+      workspace.total_num_padded_tokens, workspace.cta_idx_xy_to_batch_idx,
+      workspace.cta_idx_xy_to_mn_limit, workspace.bmm1_workspace,
+      args.mUseRoutingScalesOnInput, device, stream, config.gemm1Config,
+      enable_pdl);
+
+  // We do not fuse activation with FC1 for DeepSeek FP8 due to the weights
+  // shuffling constraint.
+  void *gemm2_input = workspace.gemm1_output;
+  void *gemm2_input_scale = workspace.gemm1_output_scale;
+  // We do activation only for DeepSeek FP8, as cubins do not have fused
+  // activation.
+  if (args.mDtypeElt == btg::Dtype::E4m3 && args.mUseDeepSeekFp8) {
+    // GEMM1-LoRA overlap: activation consumes gate_up_lora_delta, so wait on
+    // the LoRA side-stream event HERE (not before the op) -- permute+GEMM1
+    // above overlapped the side-stream LoRA shrink/expand. nullptr event = no
+    // wait (serial / non-overlap path).
+    if (args.lora_ready_event != nullptr) {
+      cudaStreamWaitEvent(stream,
+                          static_cast<cudaEvent_t>(args.lora_ready_event), 0);
+    }
+    // Run activation
+    moe::dev::activation::run(activationData, stream);
+    gemm2_input = workspace.activation_output;
+    gemm2_input_scale = workspace.activation_output_scale;
+  } else if (mUsePerTokenScalingGemm2) {
+    // TODO(siyuan): currently only support per-token nvfp4 quantization
+    FLASHINFER_CHECK(mPermuteGemm1.mDtypeOutput == btg::Dtype::Bfloat16,
+                     "When using explicit quantization, PermuteGemm1 output "
+                     "dtype must be Bfloat16.");
+    FLASHINFER_CHECK(
+        mGemm2.mDtypeAct == btg::Dtype::E2m1,
+        "Currently only support NvFP4 when using explicit quantization.");
+    FLASHINFER_CHECK(workspace.token_scales_fc2 != nullptr,
+                     "workspace.token_scales_fc2 must be provided When using "
+                     "explicit quantization.");
+    // FIXME(siyuan): Detect from the kernel config. Currently only tile size >=
+    // 128 will use R128c4
+    auto sfLayout = mGemm2.mTileTokensDim >= 128
+                        ? QuantizationSFLayout::SWIZZLED_128x4
+                        : QuantizationSFLayout::SWIZZLED_8x4;
+
+    float globalScaleInv = 1.f / (448.f * 6.f);
+    if (tensorrt_llm::common::getEnvNVFP4Use4Over6() &&
+        tensorrt_llm::common::getEnvNVFP44Over6E4M3Use256()) {
+      globalScaleInv = 1.f / (256.f * 6.f);
+    }
+    invokeNvfp4QuantAndPerTokenScale<__nv_bfloat16>(
+        args.num_tokens * args.top_k, args.intermediate_size,
+        reinterpret_cast<__nv_bfloat16 const *>(workspace.gemm1_output),
+        globalScaleInv, workspace.expanded_idx_to_permuted_idx,
+        reinterpret_cast<uint8_t *>(workspace.activation_output),
+        reinterpret_cast<uint8_t *>(workspace.activation_output_scale),
+        reinterpret_cast<float *>(workspace.token_scales_fc2), sfLayout,
+        stream);
+
+    gemm2_input = workspace.activation_output;
+    gemm2_input_scale = workspace.activation_output_scale;
+  }
+
+  // Run gemm2
+  mGemm2.run(gemm2_input, gemm2_input_scale, args.gemm2_weights,
+             args.gemm2_weights_scale, workspace.token_scales_fc2,
+             /*perChannelScales*/ nullptr, args.output2_scales_scalar,
+             args.gemm2_bias, workspace.gemm2_output,
+             workspace.gemm2_output_scale, args.top_k, args.hidden_size,
+             args.intermediate_size, args.local_num_experts, args.num_tokens,
+             workspace.num_non_exiting_ctas, workspace.total_num_padded_tokens,
+             workspace.cta_idx_xy_to_batch_idx,
+             workspace.cta_idx_xy_to_mn_limit, workspace.bmm2_workspace, device,
+             stream, config.gemm2Config, enable_pdl);
+
+  // Down-LoRA/finalize overlap: signal "base down GEMM done" so the LoRA side
+  // stream can start the down-proj LoRA shrink/expand concurrent with the
+  // finalize below. 0 = no-op.
+  if (args.gemm2_done_event != nullptr) {
+    cudaEventRecord(static_cast<cudaEvent_t>(args.gemm2_done_event), stream);
+  }
+
+  // Run finalize
+  if (args.do_finalize) {
+    // Run finalize
+    moe::dev::finalize::run(finalizeData, stream);
+    sync_check_cuda_error(stream);
+  }
+}
