+  }
+
+#define LAUNCH(data, kernel, numBlocks, numThreads, smemSize, stream)          \
+  if (data.mDtypeElt == tg::Dtype::Fp16) {                                     \
+    LAUNCH_PDL(data, false, cutlass::half_t, kernel, numBlocks, numThreads,    \
+               smemSize, stream);                                              \
+  } else if (data.mDtypeElt == tg::Dtype::E4m3) {                              \
+    LAUNCH_PDL(data, false, cutlass::float_e4m3_t, kernel, numBlocks,          \
+               numThreads, smemSize, stream);                                  \
+  } else if (data.mDtypeElt == tg::Dtype::Bfloat16) {                          \
+    LAUNCH_PDL(data, false, cutlass::bfloat16_t, kernel, numBlocks,            \
+               numThreads, smemSize, stream);                                  \
+  } else {                                                                     \
+    FLASHINFER_WARN("Unsupported dtypeElt");                                   \
+  }
+
+#define LAUNCH_NUM_TOKENS_PER_CTA(data, type, numTokensPerCta, kernel,         \
+                                  numBlocks, numThreads, smemSize, stream)     \
+  if (numTokensPerCta == 4) {                                                  \
+    LAUNCH_PDL(data, false, LAUNCH_ESC(type, 4), kernel, numBlocks,            \
+               numThreads, smemSize, stream);                                  \
+  } else if (numTokensPerCta == 2) {                                           \
+    LAUNCH_PDL(data, false, LAUNCH_ESC(type, 2), kernel, numBlocks,            \
+               numThreads, smemSize, stream);                                  \
+  } else if (numTokensPerCta == 1) {                                           \
+    LAUNCH_PDL(data, false, LAUNCH_ESC(type, 1), kernel, numBlocks,            \
+               numThreads, smemSize, stream);                                  \
+  } else {                                                                     \
+    FLASHINFER_WARN("Unsupported numTokensPerCta");                            \
