+// The type of method in top-K routing, for use in torch custom op
+// Please keep this in sync with the counterpart defined in
+// flashinfer/fused_moe/core.py
+enum class RoutingMethodType : int64_t {
+  // Default: Softmax -> TopK
+  Default = 0,
+  // Renormalize: TopK -> Softmax
+  Renormalize = 1,
+  // DeepSeekV3: Sigmoid -> RoutingBiasAdd -> Top2 in group -> Top4 groups ->
+  // Top8 experts from the
+  // Top4 groups
+  DeepSeekV3 = 2,
+  // Llama4: Top1 -> Sigmoid
+  Llama4 = 3,
+  // RenormalizeNaive: Softmax -> TopK -> Renormalize
+  RenormalizeNaive = 4,
+  // TopK only (no softmax)
+  TopK = 5,
+  // SigmoidRenorm: Sigmoid -> TopK -> Renormalize (divide by sum of top-K
+  // weights)
+  SigmoidRenorm = 6,
+  // MiniMax2: Sigmoid + Bias -> TopK -> ScaledSumNormalize (routeScale=1.0,
+  // epsilon=1e-20)
+  MiniMax2 = 7,
+  // Sigmoid: Sigmoid -> TopK (no renormalization)
+  Sigmoid = 8,
+  // Unspecified
+  Unspecified = 9,
+};
